/**
 * @file lv_font_tool_compat.c
 * Glyph callbacks for the fonts generated by "Lvgl Font Tool" (LVGL v9 API).
 */

#include "lv_font_tool_compat.h"

static int32_t glyph_find(const lv_font_fmt_txt_dsc_t * fdsc, uint32_t letter, lv_font_tool_lookup_t lookup)
{
    const lv_font_fmt_txt_cmap_t * cmap = &fdsc->cmaps[0];
    const uint16_t * list = cmap->unicode_list;

    if(letter < cmap->range_start) return -1;

    if(lookup == LV_FONT_TOOL_LOOKUP_SORTED) {
        if(letter > cmap->range_length) return -1;

        int32_t low = 0;
        int32_t high = (int32_t)cmap->list_length - 1;
        while(low <= high) {
            int32_t mid = (low + high) >> 1;
            if(letter < list[mid]) high = mid - 1;
            else if(letter > list[mid]) low = mid + 1;
            else return mid;
        }
        return -1;
    }

    for(int32_t i = 0; list[i] != 0; i++) {
        if(list[i] == letter) return i;
    }
    return -1;
}

bool lv_font_tool_get_glyph_dsc(const lv_font_t * font, lv_font_glyph_dsc_t * dsc_out, uint32_t unicode_letter,
                                lv_font_tool_lookup_t lookup)
{
    const lv_font_fmt_txt_dsc_t * fdsc = (const lv_font_fmt_txt_dsc_t *)font->dsc;

    int32_t i = glyph_find(fdsc, unicode_letter, lookup);
    if(i < 0) return false;

    const lv_font_fmt_txt_glyph_dsc_t * gdsc = &fdsc->glyph_dsc[i];
    /* the tool stores adv_w in pixels, not in 1/16 pixels like lv_font_fmt_txt */
    dsc_out->adv_w = gdsc->adv_w;
    dsc_out->box_h = gdsc->box_h;
    dsc_out->box_w = gdsc->box_w;
    dsc_out->ofs_x = gdsc->ofs_x;
    dsc_out->ofs_y = gdsc->ofs_y;
    dsc_out->stride = 0;
    dsc_out->format = (lv_font_glyph_format_t)fdsc->bpp;
    dsc_out->is_placeholder = false;
    dsc_out->gid.index = (uint32_t)i;

    return true;
}

const void * lv_font_tool_get_glyph_bitmap(lv_font_glyph_dsc_t * g_dsc, lv_draw_buf_t * draw_buf)
{
    static const uint8_t opa2_table[4] = {0, 85, 170, 255};

    const lv_font_t * font = g_dsc->resolved_font;
    const lv_font_fmt_txt_dsc_t * fdsc = (const lv_font_fmt_txt_dsc_t *)font->dsc;
    const lv_font_fmt_txt_glyph_dsc_t * gdsc = &fdsc->glyph_dsc[g_dsc->gid.index];
    const uint8_t * bitmap_in = &fdsc->glyph_bitmap[gdsc->bitmap_index];

    if(g_dsc->req_raw_bitmap) return bitmap_in;

    if(draw_buf == NULL) return NULL;
    if(gdsc->box_w == 0 || gdsc->box_h == 0) return NULL;

    /* the rows are packed continuously, unpack them to A8 */
    uint8_t * bitmap_out = draw_buf->data;
    uint32_t stride_out = lv_draw_buf_width_to_stride(gdsc->box_w, LV_COLOR_FORMAT_A8);
    uint32_t bpp = fdsc->bpp;
    uint32_t mask = (1U << bpp) - 1U;
    uint32_t bit_pos = 0;

    for(uint32_t y = 0; y < gdsc->box_h; y++) {
        for(uint32_t x = 0; x < gdsc->box_w; x++) {
            uint32_t v;
            if(bpp == 8) {
                v = bitmap_in[bit_pos >> 3];
            }
            else {
                uint32_t shift = 8U - bpp - (bit_pos & 7U);
                v = (bitmap_in[bit_pos >> 3] >> shift) & mask;
            }
            bit_pos += bpp;

            switch(bpp) {
                case 1:
                    bitmap_out[x] = v ? 0xFF : 0x00;
                    break;
                case 2:
                    bitmap_out[x] = opa2_table[v];
                    break;
                case 4:
                    bitmap_out[x] = (uint8_t)(v * 17U);
                    break;
                default:
                    bitmap_out[x] = (uint8_t)v;
                    break;
            }
        }
        bitmap_out += stride_out;
    }

    lv_draw_buf_flush_cache(draw_buf, NULL);
    return draw_buf;
}
